import { CacheManager } from 'cache-manager';
import { Injectable } from '@nestjs/common';
import { ApprovalToken } from './approval.model';

@Injectable()
class ApprovalCacheManager {
  private cacheManager: CacheManager;
  private cacheKey = 'approvalTokens';

  constructor() {
    this.cacheManager = CacheManager.create({
      store: 'memory',
      ttl: 600, // 10 minutes
    });
  }

  async getApprovalTokens(): Promise<ApprovalToken[]> {
    return this.cacheManager.get<ApprovalToken[]>(this.cacheKey);
  }

  async setApprovalTokens(tokens: ApprovalToken[]): Promise<void> {
    await this.cacheManager.set(this.cacheKey, tokens);
  }

  async invalidateApprovalTokens(): Promise<void> {
    await this.cacheManager.del(this.cacheKey);
  }
}

export const approvalCacheManager = new ApprovalCacheManager();

async function verifyApprovalToken(token: string): Promise<boolean> {
  const tokens = await approvalCacheManager.getApprovalTokens();
  if (!tokens) return false;
  return tokens.some(t => t.token === token);
}

