export function grep(pattern: string, text: string): boolean {
  // Sanitize the input pattern to prevent command injection
  const sanitizedPattern = escapeRegExp(pattern);
  const regex = new RegExp(sanitizedPattern, 'g');
  return regex.test(text);
}

import { Step } from './types';

export class Loop {
  private maxRetries = 5;
  private retryCounter = 0;

  async executeStep(step: Step): Promise<void> {
    while (this.retryCounter < this.maxRetries) {
      try {
        await step.execute();
        this.retryCounter = 0; // Reset counter on success
        break;
      } catch (error) {
        this.retryCounter++;
        console.warn(`Retrying step due to error: ${error.message}. Retries left: ${this.maxRetries - this.retryCounter}`);
      }
    }
    if (this.retryCounter >= this.maxRetries) {
      throw new Error(`Exceeded max retries for step: ${this.maxRetries}`);
    }
  }
}

